{"name": "create_inventory_transfer_log", "query": "
-- ============================================================
-- STEP 1: Audit log table for all transfer attempts
-- ============================================================
CREATE TABLE public.inventory_transfer_log (
    log_id               SERIAL PRIMARY KEY,
    transfer_timestamp   TIMESTAMP        NOT NULL DEFAULT NOW(),
    source_inventory_id  INTEGER          NOT NULL,
    target_inventory_id  INTEGER          NOT NULL,
    part_num             VARCHAR          NOT NULL,
    color_id             INTEGER          NOT NULL,
    quantity_transferred INTEGER          NOT NULL,
    transfer_reason      VARCHAR          NOT NULL,
    transfer_status      VARCHAR          NOT NULL
                             CHECK (transfer_status IN ('success', 'failed')),
    error_message        TEXT
);

-- Index for quick look-ups by inventory or part
CREATE INDEX idx_itl_source  ON public.inventory_transfer_log (source_inventory_id);
CREATE INDEX idx_itl_target  ON public.inventory_transfer_log (target_inventory_id);
CREATE INDEX idx_itl_part    ON public.inventory_transfer_log (part_num);
CREATE INDEX idx_itl_ts      ON public.inventory_transfer_log (transfer_timestamp DESC);

COMMENT ON TABLE public.inventory_transfer_log IS
  'Audit trail for every transfer_parts() invocation (successful and failed).';
"}

